<map version="1.0.1">
<node TEXT="t2v research"><node TEXT="方法" FOLDED="true"><node TEXT="位置思维"><node TEXT="定义"><node TEXT="一种对领域现状，趋势和关键问题的预估和判断"></node></node><node TEXT="常见表现"><node TEXT="地铁图"></node><node TEXT=""></node></node><node TEXT="有什么用（从研究的角度）"><node TEXT="寻找关键论文"><node TEXT="阅读"></node></node><node TEXT="寻找研究领域和问题"><node TEXT="做研究"></node></node><node TEXT="将更好的故事"><node TEXT="写作"></node></node></node></node><node TEXT="具体做法"><node TEXT="step 1"><node TEXT="对于准备研究的领域，搜索一下 相关的 survey，阅读，并获得大致的发展"></node></node><node TEXT="step 2"><node TEXT="阅读 survey 里提到的"><node TEXT="关键论文，理解研究领域里目前的核心方法和解决方法"></node><node TEXT="最新论文，构建一个引用链"></node></node></node><node TEXT="step 3"><node TEXT="日常关注常见的论文渠道，比如 arxiv，各种 top conference， 关键是掩饰，关键论文的作者"></node><node TEXT="搜索"><node TEXT="花式搜索，换关键词搜索"></node></node></node></node></node><node TEXT="图片生成" FOLDED="true"><node TEXT="General model"><node TEXT="GAN"><node TEXT="idea"><node TEXT="一步生成图片，使用对抗网络去做分辨，改进生成效果"></node></node><node TEXT="问题"><node TEXT="图片的分布非常复杂，很难去建模，训练很困难"></node><node TEXT="很难加入额外信息"></node></node></node><node TEXT="Diffusion model"><node TEXT="2006-DDPM (Denoising Diffusion Probabilistic Models)"><node TEXT="idea"><node TEXT="将一个复杂的分布近似为很多个正态分布的乘积"></node><node TEXT="这样就将一个复杂的问题转化为拟合正态分布了"></node></node><node TEXT="不需要太复杂的模型 + 每一步都很容易可以加入额外信息"></node><node TEXT="核心问题"><node TEXT="图片空间太大，对于一个高清图，1024*1024， 一百万个点，inference steps = 50， 也就是生成一个图片需要五千万次forward pass，计算量非常的大"></node></node></node><node TEXT="2112-Stable Diffusion"><node TEXT="idea"><node TEXT="压缩图片，在一个维数更小的空间做 forward pass，最后再转回到原空间"></node><node TEXT="Latent Diffusion Model"></node></node></node><node TEXT="2310-Latent Consistency Model"><node TEXT="进一步压缩 inference 用到的step， 从 50-&gt;4，从而实现极致加速"></node></node><node TEXT="更细致的改进"><node TEXT="架构"><node TEXT="eg. ViT"></node></node><node TEXT="数据集"><node TEXT="人脸，动画，高清等等"></node></node></node></node></node><node TEXT="进一步控制模型"><node TEXT="finetune"><node TEXT="overfitting, forgetting"></node></node><node TEXT="2110-LORA"><node TEXT="idea"><node TEXT="WX -&gt; ABX, A, B low rank"></node></node><node TEXT="目前用的很多，几十张图片就可以训练一个自己独特的模型"></node></node><node TEXT="2302-ControlNet"><node TEXT="idea"><node TEXT="保持原本的模型不变，创建一个副本用于处理增加的信息"></node><node TEXT="比 LORA 更一般，框架可以很轻松的容纳各种额外信息"></node></node><node TEXT="目前用的也很多，各类 prior info 都被引进来并训练好了拓展模型"><node TEXT="Depth"></node><node TEXT="Canny"></node><node TEXT="Pose"></node></node></node><node TEXT="在演化的过程中还有很多专用的模型"><node TEXT="比如专门做 style transfer，物体替换等等"></node><node TEXT="2306-MagicBrush"><node TEXT="text-guided image edit"></node></node></node></node><node TEXT="专用模型"><node TEXT="比如人脸，动作"><node TEXT="比较复杂，需要专门的建模"></node></node></node></node><node TEXT="视频生成"><node TEXT="根据初始信息"><node TEXT="text2video"><node TEXT="从模型角度来看中，image 和 text 其实差别不大，都是加一个编码头，如果是text，就是CLIP；如果是图片，就是 convolution"></node></node><node TEXT="image2video"></node><node TEXT="video2video"><node TEXT="各种text-based修改模型"><node TEXT="2306-ControlVideo"></node><node TEXT="2312-MagicStick"></node><node TEXT="2312-DragVideo"></node></node></node></node><node TEXT="根据方法"><node TEXT="拼接图片"><node TEXT="2307-AnimateDiff"><node TEXT="add motion dynamics to existing high-quality personalized T2Is and enabling them to generate animations"></node></node><node TEXT="核心问题"><node TEXT="图片之间的不连贯性"></node></node><node TEXT="解决方案"><node TEXT="2402-ConsistI2V"><node TEXT="spatio-temperal attention"></node><node TEXT="specialized noise initialization"></node></node><node TEXT="2406-Animate Anyone"><node TEXT="设计了 ReferenceNet + spatial attention 来保持 consistency"></node><node TEXT="聚焦在人的生成上"></node></node></node><node TEXT="工程角度"><node TEXT="t2i 生成已经非常成熟了，拥有大量的基础模型和各种社区构造的工具和工作流"></node><node TEXT="短期内是一个很好的解决方案"></node></node></node><node TEXT="general model"><node TEXT="拓展图片生成的 Diffusion model， 增加 spatial convolution"><node TEXT="解决拼接图片带来的不连贯性"></node></node><node TEXT="核心问题"><node TEXT="数据"><node TEXT="图片从最开始的 imagenet（千万级），到各家内部的大规模图片集（比如谷歌，亿级别），数据很丰富"></node></node><node TEXT="计算量非常巨大"></node></node><node TEXT="2311-Stable Video Diffusion"><node TEXT="结合各类工具，自动化构造了一个庞大的数据，并训练了一个通用模型"></node></node><node TEXT="接下来一大堆通用模型"><node TEXT="商业版"><node TEXT="sora，runway, meta movie gen，可灵，即梦等"></node></node><node TEXT="开源"><node TEXT="open sora, vidu, Vchitect, cogVideoX 等"></node></node></node></node><node TEXT="专用的" FOLDED="true"><node TEXT="动作"><node TEXT="2405-MotionFollower"></node><node TEXT="2405-MagicPose"></node><node TEXT="2406-mimicMotion"></node></node><node TEXT="人脸"><node TEXT="2403-Real3D-Portrait"></node><node TEXT="2407-LivePortrait"></node><node TEXT="2408-EMO"><node TEXT="更复杂的架构+使用高清图片训练，加强效果"></node></node></node><node TEXT="专用的方向"><node TEXT="一般如果方向很重要，会独立出来，形成一整套自己的方法"></node><node TEXT="常见发展路径是，一开始一般的问题比较难，所以大家在重要的子问题上研究，获得突破，然后尝试推广到一般情况"></node></node></node><node TEXT="当前工作重点"><node TEXT="重走图片生成的逻辑"><node TEXT="构建更强力的通用模型"><node TEXT="更大的模型，更多的数据"></node></node><node TEXT="迁移已有图片生成的研究"><node TEXT="人脸，动作，修改"></node></node></node><node TEXT="一个特别的角度"><node TEXT="如何把 图片生成的东西直接拿过来用在视频生成上"></node><node TEXT="2404-Ctrl-Adapter"><node TEXT="训练一个Adapter 来连接 视频生成的大模型 + 图片生成的控制网络"></node><node TEXT="类似的想法已经被用于拓展SD 上的 controlnet 到 SDXL"></node></node></node></node></node></node></node>
